import React, { createContext, useState, useEffect, useContext, useRef } from 'react';
import api from '../services/api';

const AuthContext = createContext(null);

export const useAuth = () => useContext(AuthContext);

export const AuthProvider = ({ children }) => {
  const [user, setUser] = useState(null);
  const [loading, setLoading] = useState(true);
  const [theme, setTheme] = useState(localStorage.getItem('theme') || 'light');
  const [notifications, setNotifications] = useState([]);

  // Ссылки для предотвращения спама при первом входе/рефреше страницы
  const isFirstAdminFetch = useRef(true);
  const isFirstClientFetch = useRef(true);
  const seenAppsRef = useRef(new Set());
  const prevLoansRef = useRef({});

  useEffect(() => {
    api.get('/auth/me')
      .then(res => setUser(res.data))
      .catch(() => setUser(null))
      .finally(() => setLoading(false));
  }, []);

  useEffect(() => {
    document.documentElement.setAttribute('data-theme', theme);
    localStorage.setItem('theme', theme);
  }, [theme]);

  const toggleTheme = () => {
    setTheme(prev => prev === 'light' ? 'dark' : 'light');
  };

  const login = async (email, password) => {
    const res = await api.post('/auth/login', { email, password });
    setUser(res.data.user);
  };

  const register = async (data) => {
    const res = await api.post('/auth/register', data);
    setUser(res.data.user);
  };

  const logout = async () => {
    await api.post('/auth/logout');
    setUser(null);
    setNotifications([]);
    localStorage.removeItem('purchaseReceipts');
    localStorage.removeItem('loanStatuses');
    localStorage.removeItem('tdStatuses');
    localStorage.removeItem('favorites');
    localStorage.removeItem('compareList');
  };

  // Методы управления уведомлениями
  const addNotification = (msg) => {
    setNotifications(prev => [...prev, { id: Math.random().toString(36).substr(2, 9), message: msg }]);
  };

  const removeNotification = (id) => {
    setNotifications(prev => prev.filter(n => n.id !== id));
  };

  const clearNotifications = () => {
    setNotifications([]);
  };

  // Фоновая проверка заявок и изменений статусов кредитов
  useEffect(() => {
    if (!user) {
      isFirstAdminFetch.current = true;
      isFirstClientFetch.current = true;
      seenAppsRef.current.clear();
      prevLoansRef.current = {};
      return;
    }

    // 1. Для АДМИНОВ / МЕНЕДЖЕРОВ: новые заявки с сайта
    const fetchNewApplications = async () => {
      if (user.role !== 'admin' && user.role !== 'manager') return;
      try {
        const res = await api.get('/admin/applications/new').catch(() => api.get('/applications'));
        const apps = res.data || [];
        
        apps.forEach(app => {
          // Если это НЕ первая загрузка при логине и такой ID мы еще не видели — уведомляем!
          if (!isFirstAdminFetch.current && !seenAppsRef.current.has(app.id)) {
            const appName = app.type === 'loan' ? 'кредит' : 'тест-драйв';
            addNotification(`Новая заявка №${app.id}! Получен запрос на ${appName}.`);
          }
          seenAppsRef.current.add(app.id);
        });
        
        isFirstAdminFetch.current = false;
      } catch (err) {
        console.log('Система отслеживания заявок активна. Ожидание эндпоинта бэкенда...');
      }
    };

    // 2. Для КЛИЕНТОВ: отслеживание одобрения кредита
    const checkClientLoanStatuses = async () => {
      if (user.role === 'admin' || user.role === 'manager') return;
      try {
        const res = await api.get('/loans/my').catch(() => api.get('/loans'));
        const loans = res.data || [];
        
        loans.forEach(loan => {
          const prevStatus = prevLoansRef.current[loan.id];
          
          // Если статус изменился по сравнению с прошлым тиком (и это не первичный вход на сайт)
          if (!isFirstClientFetch.current && prevStatus && prevStatus !== loan.status) {
            const carInfo = loan.car ? `${loan.car.brand} ${loan.car.model}` : '';
            
            if (loan.status === 'approved' || loan.status === 'Одобрено') {
              addNotification(`🎉 Ваш кредит на автомобиль ${carInfo} успешно ОДОБРЕН!`);
            } else if (loan.status === 'rejected' || loan.status === 'Отклонено') {
              addNotification(`❌ К сожалению, заявка на кредит для ${carInfo} была отклонена.`);
            }
          }
          // Запоминаем текущий статус кредита
          prevLoansRef.current[loan.id] = loan.status;
        });
        
        isFirstClientFetch.current = false;
      } catch (err) {
        // Заглушка, если ручка получения кредитов пользователя еще в разработке
      }
    };

    // Слушатель для мгновенных тестов на одном ПК (межвкладочный обмен)
    const handleStorageNotification = (e) => {
      if (e.key === 'luxury_dealer_new_app' && (user.role === 'admin' || user.role === 'manager')) {
        try {
          const appData = JSON.parse(e.newValue);
          if (appData) {
            const appName = appData.type === 'loan' ? 'кредит' : 'тест-драйв';
            addNotification(`🔥 Мгновенно: Клиент отправил форму на ${appName}!`);
          }
        } catch (err) {
          console.error(err);
        }
      }
    };

    const interval = setInterval(() => {
      fetchNewApplications();
      checkClientLoanStatuses();
    }, 5000);

    // Запускаем проверки сразу при монтировании компонента
    fetchNewApplications();
    checkClientLoanStatuses();

    window.addEventListener('storage', handleStorageNotification);

    return () => {
      clearInterval(interval);
      window.removeEventListener('storage', handleStorageNotification);
    };
  }, [user]);

  return (
    <AuthContext.Provider value={{
      user, setUser, loading, login, register, logout, theme, toggleTheme,
      notifications, addNotification, removeNotification, clearNotifications
    }}>
      {children}
    </AuthContext.Provider>
  );
};
